import math
from collections import defaultdict

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def check_solution(x, y, z):
    # Check x^3 + y^3 + z^3 - x^2y^2z^2 = 0
    LHS = x**3 + y**3 + z**3 - x**2 * y**2 * z**2
    return LHS == 0

solutions = []
results = defaultdict(list)

# Search scope:
# x=1, y in [1, 10]
# x=2, y in [2, 6]

# Iterate x=1
for x in [1]:
    for y in range(x, 11):
        C = x**3 + y**3
        divs = get_divisors(C)

        for z in divs:
            if z >= y:
                if check_solution(x, y, z):
                    solutions.append((x, y, z))
                    results[(x, y)].append(z)

# Iterate x=2
for x in [2]:
    for y in range(x, 7):
        C = x**3 + y**3
        divs = get_divisors(C)

        for z in divs:
            if z >= y:
                if check_solution(x, y, z):
                    solutions.append((x, y, z))
                    results[(x, y)].append(z)

print(f"--- Search Summary ---")
print(f"Total solutions found: {solutions}")
print("\nDetailed findings by (x, y) pair:")
for (x, y), z_list in results.items():
    print(f"Case (x, y) = ({x}, {y}): Divisors z >= {y} that satisfy the equation: {z_list}")
